PE      = 1, 16, 1, 1, 1, 1, 1, 0, 0, 1, 1,
PE_X    = 16, 1, 1, 1, 1, 1, 1, 0, 0, 1, 1,
PE_Y    = 1, 1, 1, 1, 16, 1, 1, 0, 0, 1, 1,
GLB     = 4, 1, 1, 1, 4, 1, 1, 0, 0, 1, 1,
CHIPS_X = 1, 2, 1, 1, 1, 1, 1, 0, 0, 1, 1,
CHIPS_Y = 1, 2, 1, 1, 1, 1, 1, 0, 0, 1, 1,
DRAM    = 1, 1, 1, 1, 1, 1, 1, 0, 0, 1, 1,
